                                ((ch = span[i + 1]) < 128 ? ("\0\0\0\0\udb32\u0015\udb32\u0015"[ch >> 4] & (1 << (ch & 0xF))) != 0 : RegexRunner.CharInClass((char)ch, "\0 \0ABDFHJKMNQRSTUabdfhjkmnqrstuŘŚKÅ")))
